#include <inttypes.h>
#include <stdint.h>
#include <stdlib.h>

#include "button.h"
#include "esp_err.h"
#include "esp_log.h"
#include "freertos/FreeRTOS.h"
#include "freertos/queue.h"
#include "freertos/task.h"

// Safe FSM. Password: SHORT, SHORT, LONG.
// The state itself remembers how much of the password is already correct.
typedef enum {
    TS_LOCKED,    // initial state, waiting for the 1st SHORT
    TS_GOT_S,     // got S,   waiting for the 2nd SHORT
    TS_GOT_SS,    // got S S, waiting for LONG
    TS_UNLOCKED   // password accepted
} ts_state_t;

// Event that is generated by the button.
typedef enum {
    EV_SHORT_PRESS, // got S
    EV_LONG_PRESS,  // got L
    EV_TIMEOUT      // timeout
} ts_event_t;

// Source of the event.
typedef enum {
    SRC_BUTTON, // button
} event_source_t;

// Message that is sent to the FSM task.
typedef struct {
    event_source_t source; // Source of the event.
    ts_event_t event;      // Event that is generated by the button.
} event_msg_t;

// Logs tag
static const char *TAG = "6_4_fsm";

// Macros that checks if the task was created successfully
static void check_task_created(BaseType_t result, const char *name) {
    if (result != pdPASS) {
        ESP_LOGE(TAG, "Can't create task %s (not enough heap?)", name);
        abort();
    }
}

// Returns the name of the state based on state enum value
static const char* state_name(ts_state_t state) {
    switch (state) {
        case TS_LOCKED:   return "LOCKED";
        case TS_GOT_S:    return "GOT_S";
        case TS_GOT_SS:   return "GOT_S_S";
        case TS_UNLOCKED: return "UNLOCKED";
    }
    return "?";
}

#define MAIN_TASK_PRIORITY UINT8_C(20)

#define EVENTS_QUEUE_LENGTH UINT8_C(10)
#define SAFE_INPUT_TIMEOUT_TICKS pdMS_TO_TICKS(3000)     // "user got stuck" -> reset
#define SAFE_UNLOCKED_TIMEOUT_TICKS pdMS_TO_TICKS(5000)  // unlocked safe locks itself again

#define CONSUMER_TASK_PRIORITY UINT8_C(5)
#define CONSUMER_TASK_STACK_SIZE UINT16_C(2048)

#define BUTTON_PIN GPIO_NUM_4
#define BUTTON_TASK_PRIORITY UINT8_C(8)
#define BUTTON_TASK_STACK_SIZE UINT16_C(2048)
#define BUTTON_LONG_PRESS_TICKS pdMS_TO_TICKS(1000)
#define BUTTON_DEBOUNCE_TICKS pdMS_TO_TICKS(50)

static QueueHandle_t events_queue;
static uint8_t events_queue_storage[EVENTS_QUEUE_LENGTH * sizeof(event_msg_t)];
static StaticQueue_t events_queue_ctrl;

// Map a button event to the safe's event (the only place that knows both worlds)
static ts_event_t to_safe_event(button_event_t event) {
    if (event == BUTTON_EVENT_LONG_PRESS) {
        return EV_LONG_PRESS;
    }
    return EV_SHORT_PRESS;
}

// Called by the button driver from its task (not ISR) -> plain xQueueSend is fine
static void on_button(button_event_t event, TickType_t held_ticks, void *user_ctx) {
    (void)user_ctx;

    // DEBUG: how long was the press, and were any edges lost?
    ESP_LOGI(TAG, "[BUTTON] %s, held %" PRIu32 " ms (threshold %" PRIu32 " ms), isr errors: %" PRIu32,
             button_event_name(event),
             (uint32_t) pdTICKS_TO_MS(held_ticks),
             (uint32_t) pdTICKS_TO_MS(BUTTON_LONG_PRESS_TICKS),
             button_isr_error_count());

    event_msg_t event_msg = { .event = to_safe_event(event), .source = SRC_BUTTON };
    if (xQueueSend(events_queue, &event_msg, 0) != pdTRUE) {
        ESP_LOGW(TAG, "Events queue full, %s dropped", button_event_name(event));
    }
}

/*
 * Transition table of the safe:
 *
 *  State \ Event   SHORT        LONG          TIMEOUT
 *  LOCKED          -> GOT_S     -> LOCKED     -> LOCKED
 *  GOT_S           -> GOT_SS    -> LOCKED     -> LOCKED
 *  GOT_SS          -> LOCKED    -> UNLOCKED   -> LOCKED
 *  UNLOCKED        -> LOCKED    -> LOCKED     -> LOCKED   (any press or timeout locks it again)
 */
// Result of one safe FSM step: where to go next + what to tell the user
typedef struct {
    ts_state_t next_state;
    esp_log_level_t level;  // how to log the message
    const char *message;    // NULL = nothing to report
} ts_fsm_result_t;

#define EVENT_RESULT(state, lvl, msg) ((ts_fsm_result_t){ .next_state = (state), .level = (lvl), .message = (msg) })

// One step of the safe FSM. Decides the next state and the message; does not log itself.
static ts_fsm_result_t handle_event(ts_state_t state, event_msg_t msg) {
    switch (state) {
        case TS_LOCKED:
            switch (msg.event) {
                case EV_SHORT_PRESS: return EVENT_RESULT(TS_GOT_S, ESP_LOG_INFO, "1/3 correct");
                case EV_LONG_PRESS:  return EVENT_RESULT(TS_LOCKED, ESP_LOG_WARN, "RESET: wrong press");
                case EV_TIMEOUT:     return EVENT_RESULT(TS_LOCKED,   ESP_LOG_INFO, NULL);  // nothing to reset
            }
            break;

        case TS_GOT_S:
            switch (msg.event) {
                case EV_SHORT_PRESS: return EVENT_RESULT(TS_GOT_SS, ESP_LOG_INFO, "2/3 correct");
                case EV_LONG_PRESS:  return EVENT_RESULT(TS_LOCKED, ESP_LOG_WARN, "RESET: wrong press");
                case EV_TIMEOUT:     return EVENT_RESULT(TS_LOCKED, ESP_LOG_WARN, "RESET: no press in time");
            }
            break;

        case TS_GOT_SS:
            switch (msg.event) {
                case EV_SHORT_PRESS: return EVENT_RESULT(TS_LOCKED, ESP_LOG_WARN, "RESET: wrong press");
                case EV_LONG_PRESS:  return EVENT_RESULT(TS_UNLOCKED, ESP_LOG_INFO, "*** UNLOCKED ***");
                case EV_TIMEOUT:     return EVENT_RESULT(TS_LOCKED, ESP_LOG_WARN, "RESET: no press in time");
            }
            break;

        case TS_UNLOCKED:
            switch (msg.event) {
                case EV_SHORT_PRESS: return EVENT_RESULT(TS_LOCKED, ESP_LOG_INFO, "Safe locked again (press)");
                case EV_LONG_PRESS:  return EVENT_RESULT(TS_LOCKED, ESP_LOG_INFO, "Safe locked again (press)");
                case EV_TIMEOUT:     return EVENT_RESULT(TS_LOCKED, ESP_LOG_INFO, "Safe locked again (auto-lock)");
            }
            break;
    }

    // unknown state/event: fail safe = locked
    return EVENT_RESULT(TS_LOCKED, ESP_LOG_ERROR, "Unknown state/event -> LOCKED");
}

// How long to wait for the next press in each state
static TickType_t state_timeout(ts_state_t state) {
    switch (state) {
        case TS_LOCKED:   return portMAX_DELAY;                // nothing to reset, wait forever
        case TS_UNLOCKED: return SAFE_UNLOCKED_TIMEOUT_TICKS;  // auto-lock
        default:          return SAFE_INPUT_TIMEOUT_TICKS;     // 3 s to enter the next press
    }
}

static event_msg_t wait_event(TickType_t timeout_ticks) {
    event_msg_t msg;

    if (xQueueReceive(events_queue, &msg, timeout_ticks) != pdPASS) {
        // no new event for the given time -> this is an event too
        return (event_msg_t){ .event = EV_TIMEOUT, .source = SRC_BUTTON };
    }
    return msg;
}

static void fsm_task(void *arg) {
    (void)arg;
    ts_state_t state = TS_LOCKED;

    ESP_LOGI(TAG, "FSM task started, state: %s. Password: SHORT SHORT LONG", state_name(state));
    for (;;) {
        event_msg_t msg = wait_event(state_timeout(state));
        ts_fsm_result_t result = handle_event(state, msg);

        if (result.message != NULL) {
            ESP_LOG_LEVEL(result.level, TAG, "%s", result.message);

            ESP_LOGI(TAG, "-------------------------------------------");
        }

        state = result.next_state;
    }

    ESP_LOGI(TAG, "FSM task finished");
}

void app_main() {
    ESP_LOGI(TAG, "Starting app");

    events_queue = xQueueCreateStatic(EVENTS_QUEUE_LENGTH, sizeof(event_msg_t), events_queue_storage, &events_queue_ctrl);
    if (events_queue == NULL) {
        ESP_LOGE(TAG, "Failed to create event queue");
        abort();

        return;
    }

    const UBaseType_t main_prio = uxTaskPriorityGet(NULL);
    vTaskPrioritySet(NULL, MAIN_TASK_PRIORITY);

    check_task_created(xTaskCreate(fsm_task, "Consumer task", CONSUMER_TASK_STACK_SIZE, NULL, CONSUMER_TASK_PRIORITY, NULL), "Consumer task");

    // events_queue must exist before this: the button callback sends into it
    const button_config_t button_config = {
        .pin = BUTTON_PIN,
        .debounce_ticks = BUTTON_DEBOUNCE_TICKS,
        .long_press_ticks = BUTTON_LONG_PRESS_TICKS,
        .task_priority = BUTTON_TASK_PRIORITY,
        .task_stack_size = BUTTON_TASK_STACK_SIZE,
        .on_event = on_button,
        .user_ctx = NULL,
    };
    ESP_ERROR_CHECK(button_init(&button_config));

    ESP_LOGI(TAG, "App initialized successfully");

    vTaskPrioritySet(NULL, main_prio);
}
